/**
 * Industry partners shown on the sponsor wall (the cards after the five
 * sponsor banners in the Sponsors section).
 *
 * Logos: put the official file at public/sponsors/<slug>.svg (or .png) and set
 * `logo`. Cards without a logo file render the wordmark in the brand colour.
 * The marks for cloudflare, solana, github, sui and stellar are generated by
 * `node scripts/build-sponsor-logos.mjs`.
 *
 * Reviews: `quote` is what the partner said about LNMHacks, in their words —
 * paste the real quote and who said it. Until then the card's hover panel
 * shows a neutral line, never an invented quote.
 */
export interface SponsorReview {
  quote: string
  by: string
  role?: string
}

export interface Sponsor {
  slug: string
  name: string
  /** Short descriptor under the card, e.g. "EDGE · CLOUD". */
  meta: string
  /** Top-right badge. */
  badge: string
  /** Brand colour used for the wordmark and the hover accent. */
  hex: string
  /** Path under public/, when an official logo file exists. */
  logo?: string
  /** What the partner said about LNMHacks; null until a real quote is in. */
  review: SponsorReview | null
}

